def TimeDelay(i, num):
    print (num)
    #time.sleep(10) 
    winsound.Beep(3000,500)
    
def ReadComPort(self):
    global sp, ComData
    if sp.isOpen():
        print(sp.inWaiting())
        ComData="" 
        #self.textEdit_23.clear()   
        while (sp.inWaiting()>0):
            # using ser.readline() assumes each line contains a single reading
            # sent using Serial.println() on the Arduino
            #reading = sp.readline()
            ReadData=sp.readline().decode('ascii', errors='ignore')   #utf-8 big5 utf-16

            self.textEdit_25.append(ReadData)
            cursor = self.textEdit_25.textCursor()
            cursor.movePosition(QtGui.QTextCursor.End)
            self.textEdit_25.setTextCursor(cursor)      
            QApplication.processEvents()
 
          
            ComData =ComData+ReadData     
    
