    def Sys_CountTimer(self):   
        global Start_Time
        #Timer to refresh clock
        T_Now = datetime.datetime.now()  #.strftime('%H:%M:%S')    #%b-%d-%y %H:%M:%S
        Start_Time=T_Now    
        self.lineEdit_1200.setText(str(T_Now.strftime("%H:%M:%S")    ) )
        self.timer = QTimer(self)
        self.timer.timeout.connect(self.showTime)
        self.timer.start(1000)
        self.showTime()
        self.show() 

        
    def showTime(self): 
        global Start_Time
        T_End=int(self.lineEdit_1379.text()  )  # Sec
        T_Now = datetime.datetime.now()  #.strftime('%H:%M:%S')    #%b-%d-%y %H:%M:%S
        Delta_T=(T_Now-Start_Time).seconds   
        self.lineEdit_1200.setText(str( Delta_T) ) 
 
        seconds = Delta_T
        t_m,t_s = divmod(seconds ,60)   
        t_h,t_m = divmod(t_m,60)
        r_t = str(int(t_h)).zfill(2) + ":" + str(int(t_m)).zfill(2) + ":" + str(int(t_s)).zfill(2)   
        
        self.lcdNumber.display(strftime( str(r_t )  )  )
        QApplication.processEvents()    
        if int(Delta_T) >= T_End:
            self.timer.stop()
            winsound.PlaySound("C:\\00_ATE System Waveform\\classic_ring_1Sec.wav", winsound.SND_FILENAME)     
            winsound.PlaySound("C:\\00_ATE System Waveform\\classic_ring_1Sec.wav", winsound.SND_FILENAME)        
