        Value=self.SCOPE1.read()      
        Vmax=str("%.3f" % float( Value))                 # MAX
        self.SCOPE1.write('MEASU:MEAS3:VALue?')   
        Value=self.SCOPE1.read()      
        Vmin=str("%.3f" % float( Value))                  # MIN
