    def DynamicLoad_FALL_SaveWaveform(self):      
        global T_Scale  
        if self.radioButton_44.isChecked():
            LoadPercent=self.radioButton_44.text()
        if self.radioButton_45.isChecked():
            LoadPercent=self.radioButton_45.text()        
        if self.radioButton_48.isChecked():
            LoadPercent=self.radioButton_48.text()     
        #---------------------------------------------------------
        T_Scale='100uS'          
        #---------------------------------------------------------    
        self.SCOPE1.write("ACQuire:STATE STOP")
        time.sleep(1) 

        if self.radioButton_168.isChecked():     #5000 series scope  
            self.SCOPE1.write('HARDCopy:FILEName "C:/Temp/Temp.PNG"')
            self.SCOPE1.write("HardCopy START")
            DC_Name=self.lineEdit_583.text()   
            fileName = self.lineEdit_346.text()+DC_Name +'_'+LoadPercent+'_'+'FALL'+'_'+T_Scale+'.PNG'          #"D:\\MSO5204.jpg"
            time.sleep(1) 
            self.SCOPE1.query("*OPC?")
            time.sleep(1) 
            self.SCOPE1.write('FILESystem:READFile "C:/Temp/Temp.PNG"')  # Read image file from instrument
            imgData = self.SCOPE1.read_raw(1024*768)   #1024*768
            file = open(fileName, "wb")
         # Save image data to local disk
            file.write(imgData)
            file.close()    
            self.SCOPE1.write('FILESystem:DELEte "C:/Temp/Temp.PNG"')
            
            self.label_672.setPixmap(QtGui.QPixmap( fileName ))
            winsound.Beep(1000,500)  
            self.SCOPE1.write('CURSOR:STATE OFF') 
            
        if self.radioButton_167.isChecked():     #4000 series scope 
            #===============================================
            self.SCOPE1.write('SAVE:IMAG:FILEF PNG')
            self.SCOPE1.write("HARDCOPY START")
            imgData = self.SCOPE1.read_raw()        
            fileName = self.lineEdit_346.text()+DC_Name +'_'+LoadPercent+'_'+'FALL'+'_'+T_Scale+'.PNG'          #"D:\\MSO5204.jpg"
            file = open(fileName, "wb")
            # Save image data to local disk
            file.write(imgData)
            file.close()                
            winsound.Beep(1000,500)      
            self.label_672.setPixmap(QtGui.QPixmap( fileName ))

 

