    @with_goto
    def SRD7_6_9_Undershoot(self):  
        global   Undershoot_Load, FallTime, Undershoot   
 
        fileName="C:\\00_ATE System Waveform\\Start2.jpg"
        self.label_346.setPixmap(QtGui.QPixmap( fileName ))     
        self.label_347.setPixmap(QtGui.QPixmap( fileName ))   
            
        QApplication.processEvents()   
        # %%%%%%%%%%%%%%%%%%%%%%%%%%    
        #                                 Step1  ==  
        # %%%%%%%%%%%%%%%%%%%%%%%%%%   
        global LoadCondition, V_IN, V_OUT, V_EN, I_OUT, PowerOn_Load
        V_IN=float(self.lineEdit_584.text()  )
        V_EN=float(self.lineEdit_585.text()  )        
        V_OUT=float(self.lineEdit_586.text()  ) 
        I_OUT=float(self.lineEdit_587.text()  )
        # %%%%%%%%%%%%%%%%%%%%%%%%%%
        
        for i in range(1,3):   
            if i==1 :
                if self.checkBox_35.isChecked()==True:  #No Load
                    PowerOn_Load='0.01'
                else:
                    goto.Exit_Undershoot
            if i==2 :
                if self.checkBox_36.isChecked()==True:  #Full Load
                    PowerOn_Load=str(I_OUT)
                else:
                    goto.Exit_Undershoot
            # %%%%%%%%%%%%%%%%%%%%%%%%%%        
            #self.textEdit_19.clear()
            #====== Scope Initial ==========
            self.SCOPE1.write('CLEAR ALL')  
