        self.textEdit_16.clear()
        Count=0
        
        for Vin in range(1,3): 
            for Load in range(1,3): 
                #---------------------------------------------------------------------------------------
                # Set and Turn on V_IN
                #---------------------------------------------------------------------------------------
                if Vin==1: #Low V
                    Set_Vin= self.lineEdit_972.text()  
                if Vin==2: # High V
                    Set_Vin= self.lineEdit_970.text() 
                #-------------------------------------------------------------------------------------------
                Set_V=Set_Vin    
                
                Set_A= '6'   
                if self.radioButton_340.isChecked():  #N6705
                    self.N6705C.write('VOLT '+Set_V+', (@'+DC_CH+')')        
                    self.N6705C.write('CURR '+Set_A+', (@'+DC_CH+')')     
                    self.N6705C.write('VOLT:SENS:SOUR EXT, (@'+DC_CH+')')   
                    self.N6705C.write('OUTP ON, (@'+DC_CH+')')      
                if self.radioButton_341.isChecked():  #Chroma 62000P
                    self.C62000P.write('SOUR:VOLT '+Set_V)
                    self.C62000P.write('SOUR:CURR '+Set_A)
                    self.C62000P.write('CONFigure:OUTPut ON') 
                if self.radioButton_347.isChecked() and self.radioButton_374.isChecked():  #Chroma 2280S
                    self.Tek2280S.write(':VOLT '+str(Set_V))    
                    self.Tek2280S.write(':CURR '+Set_A) 
                    self.Tek2280S.write(':OUTP ON') 
 
                #---------------------------------------------------------------------------------------
                # Set and Turn V_EN  
                #---------------------------------------------------------------------------------------
