    def POE12V_ShortBeforeTurnon_AutoTest(self):   
        
        fileName="C:\\00_ATE System Waveform\\Start2.jpg"        
        self.label_1116.setPixmap(QtGui.QPixmap( fileName ))     
           
        QApplication.processEvents()      
        
        Power_OFF(self)    
        
        #@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
        #   SetScope 
        #@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
        global V_IN, V_OUT, I_OUT, V_EN, I_OUT_Min
        global LoadCondition, V_IN, V_OUT, V_EN
        V_IN=float(self.lineEdit_584.text()  )
        V_EN=float(self.lineEdit_585.text()  )        
        V_OUT=float(self.lineEdit_586.text()  )
        #V_PG=float(self.lineEdit_640.text()  )
        I_OUT=float(self.lineEdit_587.text()  )
        #==== 設定示波器 ********************************************************
        Scope_Initial(self)
        #*******************************************************************
        SetCH='3' 
        self.SCOPE1.write('SELECT:CH'+SetCH +' ON')
        Rail_Name ="Output Voltage" 
        if self.radioButton_167.isChecked():  #4000 series scope         
            self.SCOPE1.write("CH"+SetCH +':LABel '+  '"'+Rail_Name+ '"')      
        else:  
            self.SCOPE1.write("CH"+SetCH +':LABel:NAMe '+  '"'+Rail_Name+ '"')  
  
        self.SCOPE1.write("CH"+SetCH +':COUPLING DC')
        self.SCOPE1.write("CH"+SetCH +':TERmination 1.000E+06')
        self.SCOPE1.write("CH"+SetCH +':BANDWIDTH TwEnty')
        self.SCOPE1.write("CH"+SetCH +':Position 1.0E+00')   
        self.SCOPE1.write("CH"+SetCH+":OFFSET"+" "+'0') 
        DCV_T=float(V_OUT)
        V_Scale=DCV_T/3
        self.SCOPE1.write("CH"+SetCH+":SCALE"+" "+ str(V_Scale) )
 
        #*******************************************************************
        SetCH='4'  # For current
        self.SCOPE1.write('SELECT:CH'+SetCH +' ON')
        Rail_Name ="Output Current"
        if self.radioButton_167.isChecked():  #4000 series scope         
            self.SCOPE1.write("CH"+SetCH +':LABel '+  '"'+Rail_Name+ '"')      
        else:  
            self.SCOPE1.write("CH"+SetCH +':LABel:NAMe '+  '"'+Rail_Name+ '"')  
    
        self.SCOPE1.write("CH"+SetCH +':COUPLING DC')
        self.SCOPE1.write("CH"+SetCH +':TERmination 50.0E+0')
        self.SCOPE1.write("CH"+SetCH +':BANDWIDTH TwEnty')
        self.SCOPE1.write("CH"+SetCH +':Position -4.0E+00')   
        V_Scale= self.lineEdit_472.text()       
        self.SCOPE1.write("CH"+SetCH+":SCALE"+" "+V_Scale) 
        
        #******************************************************** 
        # 依據選取設定Time scale
        #self.SCOPE1.write('HORizontal:MODE CONstant')
        #self.SCOPE1.write('HORizontal:MODE MANual')
        #self.SCOPE1.write('HORizontal:MODE:SAMPLERate 200.0E+6') 
        #self.radioButton_121.setChecked(True) 
        #SetTimeScale(self)
 
        # ******************************************************** 
        # ====== Trigger  Setting ========
        # ******************************************************* 
        self.SCOPE1.write('TRIGger:A:Mode NORMal')
        T_Scale= self.lineEdit_471.text()      #"0.04" # 1 second
        T_POSition= self.lineEdit_461.text() 
        SAMPLERate='10000000' #float(self.lineEdit_692.text())*1000000    
        if self.radioButton_167.isChecked():  #4000 series scope
            self.SCOPE1.write('HORizontal:POSition '+T_POSition)   
            self.SCOPE1.write("HORizontal:SCAle "+T_Scale)  
            self.SCOPE1.write("HORizontal:DELay:MODe OFF") 
        else:    
            self.SCOPE1.write('HORizontal:MAIn:POSition '+T_POSition)
            self.SCOPE1.write("HORizontal:MODE:SCAle "+T_Scale) #5204  
            self.SCOPE1.write('HORizontal:MODE:SAMPLERate '    +str(SAMPLERate) )  
        self.SCOPE1.write('TRIGGER:A:EDGE:SOURCE CH3')
        self.SCOPE1.write('TRIGGER:A:EDGE:SLOPE RISE')    
        #TTL=str((float(DCI_Max)*0.2))  <==========Current
        TTL=str((float(V_OUT)*float(self.lineEdit_456.text() )))   
        self.SCOPE1.write('TRIGGER:A:LEVEL:CH3 '+TTL)
        self.SCOPE1.write('TRIGger:A:Mode Auto')           
        # ======= Signle Trigger  ===========
        self.SCOPE1.write('ACQuire:STOPAfter SEQuence')  # or RUNSTop    
        
        #====== Set data ==========
        self.SCOPE1.write('MEASU:MEAS1:STATE ON')
        self.SCOPE1.write('MEASU:MEAS1:SOURCE CH4')
        self.SCOPE1.write('MEASU:MEAS1:Type MAX')    
        self.SCOPE1.write('MEASU:MEAS2:STATE ON')
        self.SCOPE1.write('MEASU:MEAS2:SOURCE CH4')
        self.SCOPE1.write('MEASU:MEAS2:Type MEAN')  
        self.SCOPE1.write('MEASU:MEAS3:STATE ON')
        self.SCOPE1.write('MEASU:MEAS3:SOURCE CH4')
        self.SCOPE1.write('MEASU:MEAS3:Type HIGH')
        #self.SCOPE1.write('MEASU:MEAS4:STATE ON')
        #self.SCOPE1.write('MEASU:MEAS4:SOURCE CH4')
        #self.SCOPE1.write('MEASU:MEAS4:Type PK2PK')

        
        winsound.Beep(1000, int(float(self.lineEdit_749.text()  )*1000) )
        #@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
        #   Short  ON
        #@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@ 
        DC_CH=self.lineEdit_259.text()
        LOAD_CH=self.lineEdit_260.text()       
        Load_DR= self.lineEdit_1107.text() 
        #  (Load : 1)      N6791A
        if self.radioButton_345.isChecked():                # N6791A
            Load_Set='15'
            self.N6705C.write('CURR '+Load_Set+', (@'+LOAD_CH+')')    
            self.N6705C.write('VOLT:SENS:SOUR EXT, (@'+LOAD_CH+')')    
            self.N6705C.write('OUTP ON, (@'+LOAD_CH+')')    
            self.N6705C.write('OUTP:SHOR ON,(@'+LOAD_CH+')')     
        #  (Load : 2)     CHroma 63030 
        if self.radioButton_346.isChecked():                # CHroma 63030    
            if self.radioButton_371.isChecked() :  # CR mode    
                self.Chroma_Load.write('MODE:RES:A') 
                self.Chroma_Load.write('RES:RANG MAX') 
                self.Chroma_Load.write('RES:A '+Load_DR ) 
            self.Chroma_Load.write('LOAD:SHOR ON')   
            
        #  (Load : 3)     63003-150-40
        if self.radioButton_348.isChecked(): 
            if self.radioButton_371.isChecked() :
                self.Chroma_Load.write('CHAN 1')  # 
                self.Chroma_Load.write('MODE CRL')  # CRL or CRH  
                self.Chroma_Load.write('RES:STAT:L1 '+Load_DR)
            self.Chroma_Load.write('LOAD:SHOR ON')   
            
        #  (Load : 4)     63003-150-40
        if self.radioButton_357.isChecked():  #----- 63003-150-40/6334
            if self.checkBox_30.isChecked():  #  #是否使用雙Load (6334)
                #self.Chroma_Load.write('SYNC:RUN ON')          
                self.Chroma_Load.write('LOAD ON') 
                self.Chroma_Load.write('CHAN 1')  
                self.Chroma_Load.write('LOAD:SHOR ON')  
                self.Chroma_Load.write('CHAN 3')  
                self.Chroma_Load.write('LOAD:SHOR ON') 
            else:
                if self.radioButton_371.isChecked() :
                    self.Chroma_Load.write('CHAN 1')  # 
                    self.Chroma_Load.write('MODE CRL')  # CRL or CRH  
