        winsound.Beep(1000, int(float(self.lineEdit_751.text()  )*1000) )
        
        #@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
        # POE12V_ShortCircuit_ShortOFF
        #@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
