    def Calculate(self):   
        self.lineEdit_659.setText('0')
        self.lineEdit_658.setText('0')
        self.lineEdit_657.setText('0' )     
        self.lineEdit_716.setText('0' )
        self.lineEdit_715.setText('0')
        self.lineEdit_714.setText('0')


        V_IN=float(self.lineEdit_584.text()  )
        if V_IN>30 :
            self.lineEdit_659.setText(str("%.3f" % float( V_IN*0.9)) )
            self.lineEdit_658.setText(str(V_IN))
            self.lineEdit_657.setText(str("%.3f" % float( V_IN*1.1)) )
        else:    
            self.lineEdit_716.setText(str("%.3f" % float( V_IN*0.9)) )
            self.lineEdit_715.setText(str(V_IN))
            self.lineEdit_714.setText(str("%.3f" % float( V_IN*1.1)) )
            
        winsound.Beep(3000,200)  
        
