    def SOLO_LineTransient_SetVin(self):   
        global V_IN
        V_IN=float(self.lineEdit_584.text()  ) 
        V_EN=float(self.lineEdit_585.text()  )    
        
        #***********************
        # Set Trig
        #***********************
        #This command selects or returns whether the B trigger occurs after a specified
        #      number of events or a specified period of time after the A trigger.
        #self.SCOPE1.write('TRIGger:B:STATE ON') 
        #self.SCOPE1.write('TRIGGER:B:BY EVENTS') 
        #self.SCOPE1.write('TRIGger:B:EVENTS:COUNt 10')  
        #self.SCOPE1.write('TRIGGER:B:EDGE:SOURCE CH1')    
        
 
        self.SCOPE1.write('HORIZONTAL:DELAY:MODE ON')      
        self.SCOPE1.write('HORIZONTAL:DELAY:TIME 5.0E-3')    
        
        self.SCOPE1.write('TRIGger:A:Mode Auto')              
        self.SCOPE1.write('TRIGger:A:Mode NORMal')            
        self.SCOPE1.write('ACQuire:STATE ON')  
        self.SCOPE1.write('ACQuire:STOPAfter RUNSTop')        
        self.SCOPE1.write('ACQuire:NUMAVg 10')     
        
        self.SCOPE1.write('DISplay:PERSistence ON')  
        self.SCOPE1.write('DISplay:PERSistence INFPersist')   
        Count=  int(self.lineEdit_483.text()  )     
            
        for i in range(10): 
            V_IN=float(self.lineEdit_584.text()  )     
            Power_ON(self)      

            T_POSition= '50' #self.lineEdit_461.text() 
            self.SCOPE1.write('HORizontal:MAIn:POSition '+T_POSition)
            self.SCOPE1.write('TRIGGER:A:EDGE:SOURCE CH1')
            if self.radioButton_67.isChecked():  
                self.SCOPE1.write('TRIGGER:A:EDGE:SLOPE RISE')   
                TTL=str((float(V_IN)*1.05) )  
            if self.radioButton_66.isChecked():  
                self.SCOPE1.write('TRIGGER:A:EDGE:SLOPE FALL')      
                TTL=str((float(V_IN)*0.95))     
            #TTL=str((float(DCI_Max)*0.2))  <==========Current 
            self.SCOPE1.write('TRIGGER:A:LEVEL:CH1 '+TTL)
            Time=  int(self.lineEdit_484.text()  ) *1000  
            winsound.Beep(1000,Time)        
            
            #***********************
            # Set Vin 
            #***********************
