    def Start_Load_Test(self):    
        global  DC_CH, LAOD_CH , PowerOn_Load 
        global Count_A , Max_Count, Count
        T_Now = datetime.datetime.now()        # Get the current time 
  
        Max_Count=   int( float(self.lineEdit_285.text()  ) +1)
