    def ComOpen(self):
        global sp
        global ComData, timer_SP_Read 
        
        #獲取可用的 COM port
        coms=serial.tools.list_ports.comports()
        for a in coms:
            self.textEdit_23.append(str((a )) )
            #每次修改内容，自动将光标移到最后
            cursor = self.textEdit_23.textCursor()
            cursor.movePosition(QtGui.QTextCursor.End)
            self.textEdit_23.setTextCursor(cursor)    
        winsound.Beep(3000,500) 
        str_current=str(a )  #COM12 - USB Serial Port (COM12)
        Str1=str_current.find("COM")+3    #21
        Str2=str_current.find("- USB")
        Value=str_current[Str1:Str2]
        self.lineEdit_74.setText(str((Value)) )        
        self.lineEdit_138.setText(str((Value)) )        
        sp = serial.Serial()
        sp.port = 'COM'+self.lineEdit_74.text()   
        sp.baudrate =self.comboBox_52.currentText()  
        sp = serial.Serial('COM'+self.lineEdit_74.text()  ,sp.baudrate, timeout=1)
        #sp = serial.Serial('COM'+self.lineEdit_74.text()  ,9600, timeout=1, rtscts=1)   
        #sp.timeout = 5

        if(sp.isOpen() == True):
            print ('Port opened')  
            self.textEdit_23.append('Port opened') 
        else:    
            sp.open()           
            print ('Port open')  
            self.textEdit_23.append('Port open') 
            
        #-------------------------------------------------------------------------------  
        if sp.isOpen():
            print(sp.inWaiting())
            while (sp.inWaiting()>0):
                # using ser.readline() assumes each line contains a single reading
                # sent using Serial.println() on the Arduino
                reading = sp.readline().decode('utf-8')
                # reading is a string...do whatever you want from here
                print(reading)

        cursor = self.textEdit_23.textCursor()
        cursor.movePosition(QtGui.QTextCursor.End)
        self.textEdit_23.setTextCursor(cursor)        
        ComData =''
        #********************************************************************
        self.timer_SP_Read = pg.QtCore.QTimer()
        self.timer_SP_Read.setSingleShot(False)
        self.timer_SP_Read.timeout.connect(self.ReadCom)    #Efficiency_Plot_Excel
        Interval=10   #int(self.lineEdit_492.text())*1000   
        self.timer_SP_Read.start(Interval)
        #********************************************************************
        winsound.Beep(3000,500)   
            
    def ReadCom(self):   
        global sp  
        global ComData 
        if sp.inWaiting() >0:
            thread_1 = threading.Thread(target=ReadComPort(self))  # 例項化一個執行緒物件，使執行緒執行這個函式
            thread_1.start()  # 啟動這個執行緒
            
            
    def ComClose(self):
        if(sp.isOpen() == True):
            sp.close()
        print ('Port closed')  
        winsound.Beep(3000,500)  
                 
