        file.write(imgData)
        file.close()    
        self.SCOPE1.write('FILESystem:DELEte "C:/Temp/Temp.PNG"')
        if self.radioButton_207.isChecked():  #No Load
            self.label_896.setPixmap(QtGui.QPixmap( fileName ))  
        if self.radioButton_235.isChecked():  #No Load
            self.label_894.setPixmap(QtGui.QPixmap( fileName ))         
        if self.radioButton_208.isChecked():  #No Load
            self.label_988.setPixmap(QtGui.QPixmap( fileName ))     
        
        
        QApplication.processEvents()       
  
        winsound.PlaySound("C:\\00_ATE System Waveform\\classic_ring_1Sec.wav", winsound.SND_FILENAME)      

    
    
        
        
