    def POE12V_LineRegulation_AutoTest(self):  
        global V_IN, V_OUT, I_OUT, V_EN , I_IN   , I_OUT_Min
        global LoadCondition, V_IN, V_OUT, V_EN
        
        global LineRegulation_Vout , LineRegulation_Vin, LineRegulation_Load
        
        global LineRegulation_Load, LineRegulation_Vout
        LineRegulation_Vin=          ['NA', 'NA','NA' , 'NA', 'NA', 'NA' ]
        LineRegulation_Load=        ['NA', 'NA','NA' , 'NA', 'NA', 'NA' ]
        LineRegulation_Vout=        ['NA', 'NA','NA' , 'NA', 'NA', 'NA' ]
   
        V_IN=float(self.lineEdit_584.text()  )
        V_EN=float(self.lineEdit_585.text()  )        
        V_OUT=float(self.lineEdit_586.text()  )
        #V_PG=float(self.lineEdit_640.text()  )
        I_OUT=float(self.lineEdit_587.text()  )
        
        self.textEdit_16.clear()
        Count=0
        
        for Vin in range(1,4): 
            for Load in range(1,3): 
                #---------------------------------------------------------------------------------------
                # Set and Turn on V_IN
                #---------------------------------------------------------------------------------------
                if  V_OUT<=6: #  ( <= 5V) 
                    if Vin==1:
                        Set_Vin= self.lineEdit_716.text()  
                    if Vin==2:
                        Set_Vin= self.lineEdit_715.text() 
                    if Vin==3:
                        Set_Vin= self.lineEdit_714.text() 
                else:
                    if Vin==1:
                        Set_Vin= self.lineEdit_659.text()  
                    if Vin==2:
                        Set_Vin= self.lineEdit_658.text() 
                    if Vin==3:
                        Set_Vin= self.lineEdit_657.text() 
                #-------------------------------------------------------------------------------------------
                Set_V=Set_Vin    
                
                Set_A= '6'   
                if self.radioButton_340.isChecked():  #N6705
                    self.N6705C.write('VOLT '+Set_V+', (@'+DC_CH+')')        
                    self.N6705C.write('CURR '+Set_A+', (@'+DC_CH+')')     
                    self.N6705C.write('VOLT:SENS:SOUR EXT, (@'+DC_CH+')')   
                    self.N6705C.write('OUTP ON, (@'+DC_CH+')')      
                if self.radioButton_341.isChecked():  #Chroma 62000P
                    self.C62000P.write('SOUR:VOLT '+Set_V)
                    self.C62000P.write('SOUR:CURR '+Set_A)
                    self.C62000P.write('CONFigure:OUTPut ON') 
                if self.radioButton_347.isChecked() and self.radioButton_374.isChecked():  #Chroma 2280S
                    self.Tek2280S.write(':VOLT '+str(Set_V))    
                    self.Tek2280S.write(':CURR '+Set_A) 
                    self.Tek2280S.write(':OUTP ON') 
 
                #---------------------------------------------------------------------------------------
                # Set and Turn V_EN  
                #---------------------------------------------------------------------------------------
                # Set and Turn V_EN  
                if self.checkBox_14.isChecked(): 
                    Enable_ON(self)     
                
                #---------------------------------------------------------------------------------------
                # Set and turn on load  
                #---------------------------------------------------------------------------------------
                if Load==1:
                    Set_A= '0'
                if Load==2:
                    Set_A= I_OUT   # Full load        
                    
                Load_Set= str(Set_A)          
                
                if self.radioButton_345.isChecked():                # N6791A
                    self.N6705C.write('CURR '+Load_Set+', (@'+LOAD_CH+')')    
                    self.N6705C.write('OUTP ON, (@'+LOAD_CH+')')    
                if self.radioButton_346.isChecked():                # CHroma 63030    
                    self.Chroma_Load.write('MODE:CURR:A') 
                    if float(Load_Set) >6:
                        self.Chroma_Load.write('CURR:RANG MAX') 
                    else:
                        self.Chroma_Load.write('CURR:RANG MIN')  
                    self.Chroma_Load.write('CURR:A '+str(Load_Set) ) # Old 6300 Series
                    self.Chroma_Load.write('LOAD ON') 
                if self.radioButton_348.isChecked():                #63003-150-40
                    self.Chroma_Load.write('MODE CCH')
                    self.Chroma_Load.write('CURR:STAT:L1 '+Load_Set)  
                    self.Chroma_Load.write('LOAD ON')       
                    
                if self.radioButton_357.isChecked():  #----- 63003-150-40/6334
 
                    if self.checkBox_30.isChecked():  #  #是否使用雙Load (6334)
                        self.Chroma_Load.write('SYNC:RUN OFF') 
                        #winsound.Beep(1000,500)   
                        self.Chroma_Load.write('CHAN 1') 
                        self.Chroma_Load.write('MODE CCH')        
                        self.Chroma_Load.write('CURR:STAT:L1 '+str("%.3f" % float(float(Load_Set)*0.5)) ) #63000 Series  LOAD[4=max load
                        self.Chroma_Load.write('CHAN 3') 
                        self.Chroma_Load.write('MODE CCH')         
                        self.Chroma_Load.write('CURR:STAT:L1 '+str("%.3f" % float(float(Load_Set)*0.5)) ) #63000 Series  LOAD[4=max load
                        self.Chroma_Load.write('SYNC:FRAM ON')        
                        self.Chroma_Load.write('SYNC:RUN ON') 
                    else:
                        self.Chroma_Load.write('CHAN 1') 
                        self.Chroma_Load.write('MODE CCH')        
                        self.Chroma_Load.write('CURR:STAT:L1 '+Load_Set) 
                        self.Chroma_Load.write('LOAD ON') 

        
 
                winsound.Beep(1000, int(float(self.lineEdit_936.text()  )*1000) ) 
                #---------------------------------------------------------------------------------------        
                # Output voltage  READ 輸出電壓.................................................................................
                #---------------------------------------------------------------------------------------
                if self.radioButton_170.isChecked():
                    self.Fluke45_Vout.write('MEAS1?;')
                    winsound.Beep(1000, 2000 ) 
                    Vnom=str("%.3f" % float( self.Fluke45_Vout.read()))
                    
                if self.radioButton_169.isChecked():
                    self.Keysight_34401A_1.write('MEAS:VOLT:DC?')  
                    winsound.Beep(1000, 2000 ) 
                    Vnom=str("%.3f" % float(self.Keysight_34401A_1.read()))
                    
                if self.radioButton_183.isChecked():   #DAQ34970
                    if self.radioButton_164.isChecked() or self.radioButton_183.isChecked() : 
                        scanlist = "(@101,102)"
                        scpi_str="ROUTE:SCAN "+scanlist
                        self.DAQ34970.write(scpi_str)
                        scpi_str="ROUT:CHAN:DELAY:AUTO ON"+ "," +scanlist   #每個Channel 之間的延遲時間
                        self.DAQ34970.write(scpi_str)
                        scpi_str="TRIG:COUN " + "1"    
                        self.DAQ34970.write(scpi_str)  
                        self.DAQ34970.write("INIT")     # Ferch data from 34970A 
                        self.DAQ34970.write("*OPC\n") 
                        self.DAQ34970.write('FETCH?')
                        ReadData=  self.DAQ34970.read().split(',')
                        Data = np.zeros((20,  1), dtype=np.float64)  #np.int
                        Text=''
                        for No in range(0, int(2)): 
                            Data[No]='% 6.4f' % np.float64(ReadData[No]) # Data[0]=101 , Data[1]=102
                    Vnom=str("%.3f" % float( Data[1]))
                    
                if self.radioButton_165.isChecked():   # Eload
                    if self.radioButton_345.isChecked():   #N6705C
                        self.N6705C.write('MEAS:VOLT:ACDC? (@'+LOAD_CH+')') 
                        DCV=self.N6705C.read()
                        Vnom=str("%.4f" % float(DCV))
                    if self.radioButton_346.isChecked():   #Chroma 63030 
                        self.Chroma_Load.write('MEAS:VOLT?')
                        Reading=str("%.4f" % float(self.Chroma_Load.read()))
                        Vnom=Reading   
                    if self.radioButton_348.isChecked():   #Chroma63003-150-40
                        self.Chroma_Load.write('MEAS:VOLT?')
                        Reading=str("%.4f" % float(self.Chroma_Load.read()))
                        Vnom=Reading            
                        
                LineRegulation_Vin[Count]=  Set_Vin
                LineRegulation_Load[Count]=    str("%.3f" % float(Load_Set)) 
                LineRegulation_Vout[Count]=  Vnom
                
                # @@@@@@@@@@@@@@@@@@@@@@@@@@
                # 判斷是否進入規格   Vmean < + / -    ??? % , 3 ~ 5%
                # @@@@@@@@@@@@@@@@@@@@@@@@@@
                Test_Result='PASS'
                Low_limit=float(self.lineEdit_360.text())
                High_limit=float(self.lineEdit_357.text())
                if float(LineRegulation_Vout[Count]) < Low_limit  :
                    Test_Result='Fail  (Vout < Upper_limit)'   
                if float(LineRegulation_Vout[Count]) > High_limit  :
                    Test_Result='Fail  (Vout > Upper_limit)'
                # @@@@@@@@@@@@@@@@@@@@@@@@@@   
                
                # Save to Text
                self.textEdit_16.append('LineRegulation:  '+'Vin= '+str("%.2f" % float(Set_Vin))+ \
                "  "+'Load= '+str("%.3f" % float(Load_Set))+"  "+'Vout= '+Vnom +"   "+ Test_Result)
                
                cursor = self.textEdit_16.textCursor()
                cursor.movePosition(QtGui.QTextCursor.End)
                self.textEdit_16.setTextCursor(cursor)      
                QApplication.processEvents()


                if Vin==1 and Load==1:  
                    self.lineEdit_532.setText(str("%.3f" % float( Vnom)))  
                if Vin==2 and Load==1:  
                    self.lineEdit_533.setText(str("%.3f" % float( Vnom)))    
                if Vin==3 and Load==1:  
                    self.lineEdit_534.setText(str("%.3f" % float(Vnom)))        
                    
                if Vin==1 and Load==2:  
                    self.lineEdit_551.setText(str("%.3f" % float( Vnom)) ) 
                if Vin==2 and Load==2:  
                    self.lineEdit_660.setText(str("%.3f" % float( Vnom)))   
                if Vin==3 and Load==2:  
                    self.lineEdit_661.setText(str("%.3f" % float( Vnom)))      
                    
                Count=Count+1   
                    

                QApplication.processEvents()  

                
        # 等待時間
        winsound.Beep(1000, int(float(self.lineEdit_928.text()  )*1000) )     
        
        # ============================================================================  
        Power_OFF(self)
        # ============================================================================  
        
