    def POE12V_LoadRegulation_StartTest(self):       
        global fig , chart 
        global Count, x, y, Step_Value
        global LoadRegulation_Vload, LoadRegulation_Load_I, LoadRegulation
        global axis_R, chart, graphicscene
        global ws, wb
        global LoadCondition, V_IN, V_OUT, V_EN, I_OUT, DC_CH, LAOD_CH , Set_A, PowerOn_Load
