    def POE12V_LoadTransient_SetLoad(self):   
        global V_IN, V_OUT, I_OUT, V_EN,V_PG,  I_IN, F_SW, I_OUT_Min   
        # Set Scope Run 
        self.SCOPE1.write('CLEAR ALL')                              
        self.SCOPE1.write('ACQuire:STOPAfter RUNSTop')    
        self.SCOPE1.write('ACQuire:STATE RUN')            

        #@@@@@@@@@@@@@
        #  設定電子負載
        #@@@@@@@@@@@@@
        #==== 設定 Dynamic Load ****** 
        DCI_Max=self.lineEdit_587.text()
        DCI_Min=self.lineEdit_422.text()
        if self.radioButton_213.isChecked(): #0-50%
            Hi_Load=str(float(DCI_Max)/2)
            Low_Load='0'
        if self.radioButton_214.isChecked(): #50-100%
            Hi_Load=str(DCI_Max)
            Low_Load=str(float(DCI_Max)/2)
        if self.radioButton_215.isChecked(): #         
            Hi_Load=  self.lineEdit_655.text()    #  str(float(DCI_Max)*float(self.lineEdit_654.text())/100)
            Low_Load=self.lineEdit_654.text()   # str(float(DCI_Max)*float(self.lineEdit_655.text())/100)
        

        TTL=float(Hi_Load)*0.75
        self.SCOPE1.write('TRIGGER:A:LEVEL:CH4 '+ str(TTL))
        self.SCOPE1.write('TRIGger:A:Mode Auto')        
      
        if self.radioButton_346.isChecked(): #Chroma_Load 63030
            self.Chroma_Load.write("MODE:CURR:DYN")
            self.Chroma_Load.write("CURR:H "+Hi_Load)
            self.Chroma_Load.write("CURR:L "+Low_Load )
            # ＝＝＝set Dynamic L/H Timing parameter
            Freq=float( self.lineEdit_424.text() )*1000
            T1=str("%0.6f" % float( (1/Freq)*0.5))  # 
            T2=str("%0.6f" % float( (1/Freq)*0.5))  
            self.Chroma_Load.write("CURRent:TIME:T1 "+T1)
            self.Chroma_Load.write("CURRent:TIME:T2 "+T1)
            # ＝＝＝set Dynamic Rise/FALL Slew parameter
            self.Chroma_Load.write("CURR:SLEW:DYNamic:RISE "+self.lineEdit_420.text())
            self.Chroma_Load.write("CURR:SLEW:DYNamic:FALL "+self.lineEdit_420.text()) 
            self.Chroma_Load.write('LOAD ON') 
   
        if self.radioButton_357.isChecked():      # 6334 / 63303(並聯負載)
            if self.checkBox_30.isChecked():  #  #是否使用雙Load (6334)
                self.Chroma_Load.write('SYNC:RUN OFF')  
                winsound.Beep(3000,500)
                # Set CHAN 1  =============================================   
                I_L=str( float(Hi_Load)*0.5)
                I_H=str( float(Low_Load)*0.5)
                Freq=float( self.lineEdit_424.text() )*1000  
                T1=str("%0.6f" % float( (1/Freq)*0.5))  # 
                T2=str("%0.6f" % float( (1/Freq)*0.5))  
                
                self.Chroma_Load.write('CHAN 1')   
                self.Chroma_Load.write("MODE CCDH")
                self.Chroma_Load.write("CURR:DYN:L1 "+I_L )
                self.Chroma_Load.write("CURR:DYN:L2 "+I_H )                
                # ＝＝＝set Dynamic L/H Timing parameter

                self.Chroma_Load.write("CURR:DYN:T1 "+T1)
                self.Chroma_Load.write("CURR:DYN:T2 "+T2)
                self.Chroma_Load.write("CURR:DYN:REP MAX")
                # ＝＝＝set Dynamic Rise/FALL Slew parameter
                SR1=str(float(self.lineEdit_420.text()))
                SR2=str(float(self.lineEdit_420.text()))
                self.Chroma_Load.write("CURR:DYN:RISE "+SR1)
                self.Chroma_Load.write("CURR:DYN:FALL "+SR2)
                
                # Set CHAN 3  =============================================   
                self.Chroma_Load.write('CHAN 3')   
                self.Chroma_Load.write("MODE CCDH")
                self.Chroma_Load.write("CURR:DYN:L1 "+I_L )
                self.Chroma_Load.write("CURR:DYN:L2 "+I_H )
                self.Chroma_Load.write("CURR:DYN:T1 "+T1)
                self.Chroma_Load.write("CURR:DYN:T2 "+T2)
                self.Chroma_Load.write("CURR:DYN:REP MAX")
                # ＝＝＝set Dynamic Rise/FALL Slew parameter
                SR1=str(float(self.lineEdit_420.text()))
                SR2=str(float(self.lineEdit_420.text()))
                self.Chroma_Load.write("CURR:DYN:RISE "+SR1)
                self.Chroma_Load.write("CURR:DYN:FALL "+SR2)     
                self.Chroma_Load.write('SYNC:TYPE MASTER')        
                self.Chroma_Load.write('SYNC:FRAM ON')        
                self.Chroma_Load.write('SYNC:RUN ON')  
                
                #*****************************************************     
            else:
                # Set CHAN 1  =============================================   
                I_L=str( float(Hi_Load)*1)
                I_H=str( float(Low_Load)*1)
                self.Chroma_Load.write('CHAN 1')   
                self.Chroma_Load.write("MODE CCDH")
                self.Chroma_Load.write("CURR:DYN:L1 "+I_L )
                self.Chroma_Load.write("CURR:DYN:L2 "+I_H )
                # ＝＝＝set Dynamic L/H Timing parameter
                Freq=float( self.lineEdit_424.text() )*1000
                T1=str("%0.6f" % float( (1/Freq)*0.5))  # 
                T2=str("%0.6f" % float( (1/Freq)*0.5))  
                #T1=str(float(self.lineEdit_430.text())*0.001)
                #T2=str(float(self.lineEdit_463.text())*0.001)
                self.Chroma_Load.write("CURR:DYN:T1 "+T1)
                self.Chroma_Load.write("CURR:DYN:T2 "+T2)
                self.Chroma_Load.write("CURR:DYN:REP MAX")
                # ＝＝＝set Dynamic Rise/FALL Slew parameter
                SR1=str(float(self.lineEdit_420.text()))
                SR2=str(float(self.lineEdit_420.text()))
                self.Chroma_Load.write("CURR:DYN:RISE "+SR1)
                self.Chroma_Load.write("CURR:DYN:FALL "+SR2)
                
                self.Chroma_Load.write('LOAD ON') 
                
        T_Scale= str (((1/ (float(self.lineEdit_424.text() ) *1000  ) )  * 5 )/10 )
        if self.radioButton_167.isChecked():  #4000 series scope
            self.SCOPE1.write("HORizontal:SCAle "+T_Scale)
        else:
            self.SCOPE1.write("HORizontal:MODE:SCAle "+T_Scale)   
        
        
    def POE12V_LoadTransient_PowerON(self):       
        global V_IN, V_OUT, I_OUT, V_EN,V_PG,  I_IN, F_SW, I_OUT_Min
        #  Power ON 
        # Set and Turn on V_IN
        Set_V= V_IN
        Set_A= '6' #I_IN        
        
        #@@@@@@@@@@@@@
        #  設定電源
        #@@@@@@@@@@@@@
        if self.radioButton_340.isChecked():  #N6705
            DC_CH=self.lineEdit_259.text()
            LOAD_CH=self.lineEdit_260.text()
            self.N6705C.write('VOLT '+Set_V+', (@'+DC_CH+')')    
            self.N6705C.write('CURR '+Set_A+', (@'+DC_CH+')')   
            self.N6705C.write('VOLT:SENS:SOUR EXT, (@'+DC_CH+')')   
            self.N6705C.write('OUTP ON, (@'+DC_CH+')')   
        if self.radioButton_341.isChecked():  #Chroma 62000P
            self.C62000P.write('SOUR:VOLT '+ str(Set_V))
            self.C62000P.write('SOUR:CURR '+Set_A)
            self.C62000P.write('CONFigure:OUTPut ON') 
        if self.radioButton_347.isChecked() and self.radioButton_374.isChecked():  #Chroma 2280S
            self.Tek2280S.write(':VOLT '+str(Set_V))    
            self.Tek2280S.write(':CURR '+Set_A) 
            self.Tek2280S.write(':OUTP ON') 
            
        #@@@@@@@@@@@@@
        #  設定電源 V_EN  
        #@@@@@@@@@@@@@
        if self.checkBox_14.isChecked():  
            Enable_ON(self)
                
   
            
