    def POE12V_SequenceOFF_SetScope(self):      
        global V_IN, V_OUT, I_OUT, V_EN,V_PG,  I_IN, F_SW, I_OUT_Min 
        global LoadCondition, V_IN, V_OUT, V_EN
        global PowerOn_Load  
        V_IN=float(self.lineEdit_584.text()  )
        V_EN=float(self.lineEdit_585.text()  )        
        V_OUT=float(self.lineEdit_586.text()  )
        #V_PG=float(self.lineEdit_640.text()  )
        I_OUT=float(self.lineEdit_587.text()  )
        
        # 設定示波器    %%%%%%%%%%%%%%%%%%%%%%%%%%
        #====== Scope Initial ==========
        self.SCOPE1.write('CLEAR ALL')
        self.SCOPE1.write('ACQuire:STOPAfter RUNSTop')  # or  
        self.SCOPE1.write("SELECT:CH1 OFF")
        self.SCOPE1.write("SELECT:CH2 OFF")
        self.SCOPE1.write("SELECT:CH3 OFF")
        self.SCOPE1.write("SELECT:CH4 OFF")
        self.SCOPE1.write('MEASU:MEAS1:STATE OFF')
        self.SCOPE1.write('MEASU:MEAS2:STATE OFF')
        self.SCOPE1.write('MEASU:MEAS3:STATE OFF')
        self.SCOPE1.write('MEASU:MEAS4:STATE OFF')
        self.SCOPE1.write('MEASU:MEAS5:STATE OFF')
        self.SCOPE1.write('MEASU:MEAS6:STATE OFF')
        self.SCOPE1.write('MEASU:MEAS7:STATE OFF')
        self.SCOPE1.write('MEASU:MEAS8:STATE OFF')
        self.SCOPE1.write('CURSor:FUNCtion OFF')
        self.SCOPE1.write("ACQuire:STATE RUN")
        self.SCOPE1.write('FASTAcq:STATE OFF')
        self.SCOPE1.write("SELECT:MATH1"+' OFF') 
        self.SCOPE1.write('MEASUrement:ANNOTation:STATE OFF')
        
        # Set chanel    ********************************************************************
 
        SetCH='1'  #  V_IN
        self.SCOPE1.write('SELECT:CH'+SetCH +' ON')
        CH_Label = self.lineEdit_589.text()    
        if self.radioButton_168.isChecked():     #5000 series scope             
            self.SCOPE1.write("CH"+SetCH +':LABel:NAMe '+ '"'+CH_Label+'"')   
            self.SCOPE1.write("CH"+SetCH +':BANDWIDTH TwEnty')      			
        if self.radioButton_167.isChecked():     #4000 series scope          
            self.SCOPE1.write("CH"+SetCH +':LABel '+ '"'+CH_Label+'"')     
            self.SCOPE1.write("CH"+SetCH +':BANDWIDTH 20E6') 
        self.SCOPE1.write("CH"+SetCH +':COUPLING DC')
        self.SCOPE1.write("CH"+SetCH +':TERmination 1.000E+06 ')  #1.000E+06  or  50.0E+0 
        self.SCOPE1.write("CH"+SetCH +':Position 2')
        self.SCOPE1.write("CH"+SetCH+":OFFSET"+" "+'0') 
        V_Scale =float(V_IN)/2          
        self.SCOPE1.write("CH"+SetCH+":SCALE"+" "+str(V_Scale) )
        Probe=self.lineEdit_631.text()  
        self.SCOPE1.write("CH1:PROBE "+Probe)
 
        SetCH='3'  #  V_OUT
        self.SCOPE1.write('SELECT:CH'+SetCH +' ON')
        CH_Label = self.lineEdit_591.text()  
        if self.radioButton_168.isChecked():     #5000 series scope             
            self.SCOPE1.write("CH"+SetCH +':LABel:NAMe '+ '"'+CH_Label+'"')   
            self.SCOPE1.write("CH"+SetCH +':BANDWIDTH TwEnty')      			
        if self.radioButton_167.isChecked():     #4000 series scope          
            self.SCOPE1.write("CH"+SetCH +':LABel '+ '"'+CH_Label+'"')     
            self.SCOPE1.write("CH"+SetCH +':BANDWIDTH 20E6') 
        self.SCOPE1.write("CH"+SetCH +':COUPLING DC')
        self.SCOPE1.write("CH"+SetCH +':TERmination 1.000E+06 ')  #1.000E+06  or  50.0E+0 
        self.SCOPE1.write("CH"+SetCH +':Position -1E+00')
        self.SCOPE1.write("CH"+SetCH+":OFFSET"+" "+'0') 
        V_Scale =float(V_OUT)/2            
        self.SCOPE1.write("CH"+SetCH+":SCALE"+" "+str(V_Scale) ) 
        
        if self.checkBox_22.isChecked():  # Set current channel
            SetCH='4'  # For current
            self.SCOPE1.write('SELECT:CH'+SetCH +' ON')
            CH_Label ="Output Current"
            if self.radioButton_168.isChecked():     #5000 series scope             
                self.SCOPE1.write("CH"+SetCH +':LABel:NAMe '+ '"'+CH_Label+'"')   
                self.SCOPE1.write("CH"+SetCH +':BANDWIDTH TwEnty')      			
            if self.radioButton_167.isChecked():     #4000 series scope          
                self.SCOPE1.write("CH"+SetCH +':LABel '+ '"'+CH_Label+'"')     
                self.SCOPE1.write("CH"+SetCH +':BANDWIDTH 20E6') 
            self.SCOPE1.write("CH"+SetCH +':COUPLING DC')
            self.SCOPE1.write("CH"+SetCH +':TERmination 50.0E+0 ')  #1.000E+06  or  50.0E+0 
            self.SCOPE1.write("CH"+SetCH +':Position -4.0E+00')
            V_Scale=str(float( float(I_OUT)/3  ))  # (float(DCI_Max)*1.5)/3 
            self.SCOPE1.write("CH"+SetCH+":SCALE"+" "+V_Scale)     
            
            
        # Time scale    *********************************************************************
        T_Scale= self.lineEdit_646.text()       
        if self.radioButton_167.isChecked():  #4000 series scope
            self.SCOPE1.write("HORizontal:SCAle "+T_Scale)
        else:
            self.SCOPE1.write("HORizontal:MODE:SCAle "+T_Scale)           
        
        self.SCOPE1.write('HORizontal:MODE AUTO') #{AUTO|CONStant|MANual}
        #self.SCOPE1.write('HORizontal:MODE:SAMPLERate 100.0E+6') # 10 Mega  
        RECORDLENGTH='1000000' #float(self.lineEdit_693.text()) *1000000  
        self.SCOPE1.write("HORIZONTAL:MODE:RECORDLENGTH " +str(RECORDLENGTH) )         
        SAMPLERate='1000000' #float(self.lineEdit_692.text())*1000000    
        self.SCOPE1.write('HORizontal:MODE:SAMPLERate '    +str(SAMPLERate) )  

   

        # **********************************************************************************
        
        # Trig          
        T_Source= self.lineEdit_645.text()        
        T_POSition= self.lineEdit_643.text()       
        self.SCOPE1.write('HORizontal:MAIn:POSition '+T_POSition)
        self.SCOPE1.write('TRIGGER:A:EDGE:SOURCE CH'+T_Source)
        self.SCOPE1.write('TRIGGER:A:EDGE:SLOPE FALL')    
        TTL=str((float(V_IN)*0.7))   
        self.SCOPE1.write('TRIGGER:A:LEVEL:CH'+T_Source+' '+TTL)
        self.SCOPE1.write('TRIGger:A:Mode Auto')        
        self.SCOPE1.write('TRIGger:A:Mode NORMal')       
        
        #@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
        #  Single ON Setting  4列
        #@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
        self.SCOPE1.write('CLEAR ALL')                              
        self.SCOPE1.write('ACQuire:STOPAfter RUNSTop')    
        self.SCOPE1.write('ACQuire:STATE RUN')                 
        self.SCOPE1.write('ACQuire:STOPAfter SEQUENCE')   # Single ON   
        #@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@
        
        
        #************************************************************************************
        #====== Set data ==== Type : MAX , MEAN ,MINI, RMS , HIGH
        self.SCOPE1.write('MEASU:MEAS1:STATE ON')
        self.SCOPE1.write('MEASU:MEAS1:SOURCE CH1')
        self.SCOPE1.write('MEASU:MEAS1:Type MAX')    
        self.SCOPE1.write('MEASU:MEAS2:STATE ON')
        self.SCOPE1.write('MEASU:MEAS2:SOURCE CH2')
        self.SCOPE1.write('MEASU:MEAS2:Type MAX')  
        self.SCOPE1.write('MEASU:MEAS3:STATE ON')
        self.SCOPE1.write('MEASU:MEAS3:SOURCE CH3')
        self.SCOPE1.write('MEASU:MEAS3:Type MAX')    
        
        if self.checkBox_22.isChecked():   
            self.SCOPE1.write('MEASU:MEAS4:STATE ON')
            self.SCOPE1.write('MEASU:MEAS4:SOURCE CH4')
            self.SCOPE1.write('MEASU:MEAS4:Type MAX')  
        self.SCOPE1.write('HORIZONTAL:ROLL OFF')   
        
        if self.checkBox_31.isChecked():      
            self.SCOPE1.write('MEASUrement:ANNOTation:STATE ON')   
            self.SCOPE1.write('MEASU:IMMED:DELAY:DIRECTION FORWARDS') #BACKWARDS
            self.SCOPE1.write('MEASU:MEAS5:STATE ON')      
            self.SCOPE1.write('MEASU:MEAS5:Type DELay')    
            self.SCOPE1.write('MEASU:MEAS5:DELay:EDGE1 FALL')  
            self.SCOPE1.write('MEASU:MEAS5:DELay:EDGE2 FALL') 
            self.SCOPE1.write('MEASUREMENT:MEAS5:REFLEVEL:PERCENT:MID1 10') 
            self.SCOPE1.write('MEASUREMENT:MEAS5:REFLEVEL:PERCENT:MID2 10') 
            self.SCOPE1.write('MEASU:MEAS5:SOUrce1 CH1') 
            self.SCOPE1.write('MEASU:MEAS5:SOUrce2 CH3') 
            self.SCOPE1.write('MEASUrement:ANNOTation:STATE MEAS5')
            
        Power_OFF(self)    
        
        if self.radioButton_211.isChecked():  #No Load
            PowerOn_Load=self.lineEdit_688.text()    
        if self.radioButton_212.isChecked():  #Half Load
            PowerOn_Load=str(I_OUT*0.5)      
        if self.radioButton_216.isChecked():  #Max Load
            PowerOn_Load=str(I_OUT )         

    def POE12V_SequenceOFF_SaveWaveform(self):   
        global PowerOn_Load
        #Save waveform
        
        self.SCOPE1.write("ACQuire:STATE STOP")
        time.sleep(1) 
        self.SCOPE1.write('HARDCopy:FILEName "C:/Temp/Temp.PNG"')
        self.SCOPE1.write("HardCopy START")
        Rail_Name =self.lineEdit_583.text()
 
        fileName = self.lineEdit_266.text()+"_"+Rail_Name +"_"+PowerOn_Load+'.PNG'          #"D:\\MSO5204.jpg"
        time.sleep(1) 
        self.SCOPE1.query("*OPC?")
        time.sleep(1) 
        self.SCOPE1.write('FILESystem:READFile "C:/Temp/Temp.PNG"')  # Read image file from instrument
        imgData = self.SCOPE1.read_raw(1024*768)   #1024*768
        file = open(fileName, "wb")
        # Save image data to local disk
        file.write(imgData)
        file.close()    
        self.SCOPE1.write('FILESystem:DELEte "C:/Temp/Temp.PNG"')
        
        if self.radioButton_211.isChecked():  #No Load
            PowerOn_Load=self.lineEdit_688.text()  
            self.label_468.setPixmap(QtGui.QPixmap( fileName ))     
        if self.radioButton_212.isChecked():  #Half Load
            PowerOn_Load=str(I_OUT*0.5)  
            self.label_1151.setPixmap(QtGui.QPixmap( fileName ))   
        if self.radioButton_216.isChecked():  #Max Load
            PowerOn_Load=I_OUT   
            self.label_1152.setPixmap(QtGui.QPixmap( fileName ))     
      
        QApplication.processEvents()    

        winsound.PlaySound("C:\\00_ATE System Waveform\\classic_ring_1Sec.wav", winsound.SND_FILENAME)      
        
