    def POE12V_SequenceON_SaveWaveform(self):   
        global  PowerOn_Load  
        #Save waveform
        self.SCOPE1.write("ACQuire:STATE STOP")
        time.sleep(1) 
        self.SCOPE1.write('HARDCopy:FILEName "C:/Temp/Temp.PNG"')
        self.SCOPE1.write("HardCopy START")
        Rail_Name =self.lineEdit_583.text()
 
        fileName = self.lineEdit_265.text()+"_"+Rail_Name +"_"+PowerOn_Load+'.PNG'          #"D:\\MSO5204.jpg"
        time.sleep(1) 
        self.SCOPE1.query("*OPC?")
        time.sleep(1) 
        self.SCOPE1.write('FILESystem:READFile "C:/Temp/Temp.PNG"')  # Read image file from instrument
        imgData = self.SCOPE1.read_raw(1024*768)   #1024*768
        file = open(fileName, "wb")
        # Save image data to local disk
        file.write(imgData)
        file.close()    
        self.SCOPE1.write('FILESystem:DELEte "C:/Temp/Temp.PNG"')
        
        if self.radioButton_211.isChecked():  #No Load
            PowerOn_Load=self.lineEdit_688.text()  
            self.label_396.setPixmap(QtGui.QPixmap( fileName ))     
        if self.radioButton_212.isChecked():  #Half Load
            PowerOn_Load=str(I_OUT*0.5)  
            self.label_517.setPixmap(QtGui.QPixmap( fileName ))   
        if self.radioButton_216.isChecked():  #Max Load
            PowerOn_Load=I_OUT   
            self.label_1149.setPixmap(QtGui.QPixmap( fileName ))     
      
        QApplication.processEvents()    

        winsound.PlaySound("C:\\00_ATE System Waveform\\classic_ring_1Sec.wav", winsound.SND_FILENAME)      
        
 
 



    def DCDC_TurnOff(self):   
        global DC_CH, LAOD_CH
        #======================    
        # Set  Load
        #======================
        #self.Chroma_Load.write('LOAD OFF')     
        
        # Turn off Vin
        if self.radioButton_340.isChecked():  #N6705
            self.N6705C.write('OUTP OFF, (@'+DC_CH+')')      
        if self.radioButton_341.isChecked():  #Chroma 62000P
            self.C62000P.write('CONFigure:OUTPut OFF') 
        if self.radioButton_347.isChecked() and self.radioButton_374.isChecked():  #Chroma 2280S
            self.Tek2280S.write(':OUTP OFF') 
 
            
        # Turn off Enable
        if self.checkBox_14.isChecked():    # if need enable
            Enable_OFF(self)
                
                
            
        time.sleep(2)    
        #======================    
        # Set  Load
        #======================
        Set_A='0'
           
        if self.radioButton_345.isChecked():                # N6791A
            self.N6705C.write('CURR '+Set_A+', (@'+LOAD_CH+')')    
            self.N6705C.write('OUTP OFF, (@'+LOAD_CH+')')     
        if self.radioButton_346.isChecked():                # CHroma 63030    
            self.Chroma_Load.write('MODE:CURR:A') 
            if float(Set_A) >6:
                self.Chroma_Load.write('CURR:RANG MAX') 
            else:
                self.Chroma_Load.write('CURR:RANG MIN')  
            self.Chroma_Load.write('CURR:A '+Set_A)  # Old 6300 Series
            self.Chroma_Load.write('LOAD OFF')     
        if self.radioButton_348.isChecked():  #----- 63003-150-40 
            self.Chroma_Load.write('LOAD OFF')     
        if self.radioButton_357.isChecked():  #----- 63003-150-40/6334
            if self.checkBox_30.isChecked():  #  #是否使用雙Load (6334)
                self.Chroma_Load.write('SYNC:RUN OFF') 
            else:
                self.Chroma_Load.write('LOAD OFF')      

   
    def DCDC_TurnOn(self):    
        global LoadCondition, V_IN, V_OUT, V_EN, I_OUT
        global DC_CH, LAOD_CH 
        #=================================================================    
        # Set  Load
        #================================================================
        Set_A='0'
        if LoadCondition==1:
            Set_A='0'
        if LoadCondition==2:
            Set_A=str(I_OUT)
            
        if self.radioButton_345.isChecked():                # N6791A
            self.N6705C.write('CURR '+Set_A+', (@'+LOAD_CH+')')    
            self.N6705C.write('OUTP ON, (@'+LOAD_CH+')')    
        if self.radioButton_346.isChecked():                # CHroma 63030    
            self.Chroma_Load.write('MODE:CURR:A') 
            if float(Load_Set) >6:
                self.Chroma_Load.write('CURR:RANG MAX') 
            else:
                self.Chroma_Load.write('CURR:RANG MIN')  
            self.Chroma_Load.write('CURR:A '+Set_A)  # Old 6300 Series
            self.Chroma_Load.write('LOAD ON') 
            
        #=================================================================   
        #  Power on
        #=================================================================   
        # Set and Turn on V_IN
        Set_V= V_IN
        Set_A= '6'  #I_IN        
        if self.radioButton_340.isChecked():  #N6705
            self.N6705C.write('VOLT '+Set_V+', (@'+DC_CH+')')        
            self.N6705C.write('CURR '+Set_A+', (@'+DC_CH+')')     
            self.N6705C.write('VOLT:SENS:SOUR EXT, (@'+DC_CH+')')   
            self.N6705C.write('OUTP ON, (@'+DC_CH+')')      
        if self.radioButton_341.isChecked():  #Chroma 62000P
            self.C62000P.write('SOUR:VOLT '+str(Set_V))
            self.C62000P.write('SOUR:CURR '+Set_A)
            self.C62000P.write('CONFigure:OUTPut ON') 
        if self.radioButton_347.isChecked() and self.radioButton_374.isChecked():  #Chroma 2280S
            self.Tek2280S.write(':VOLT '+str(Set_V))    
            self.Tek2280S.write(':CURR '+Set_A) 
            self.Tek2280S.write(':OUTP ON') 
        #==================================================================     
        # Set and Turn V_EN  
        #==================================================================    
        if self.checkBox_14.isChecked():    # if need enable
            Enable_ON(self)
        
        winsound.Beep(1000,1000)                 
    

