    def Load_Transient_LoadOn(self):  
        global DC_CH, LAOD_CH
        if self.radioButton_340.isChecked():  #N6705
            self.N6705C.write('OUTP OFF, (@'+DC_CH+')')   
        if self.radioButton_341.isChecked():  #Chroma 62000P
            self.C62000P.write('CONFigure:OUTPut OFF') 
        if self.radioButton_347.isChecked() and self.radioButton_374.isChecked() : 
            self.Tek2280S.write(':OUTP OFF') 
            
        self.N6705C.write("ABOR:TRAN (@4)")  
        winsound.Beep(1000,500)     
        A_Lo= self.lineEdit_409.text() 
        A_Hi = self.lineEdit_405.text() 
        T_Duty=float(self.lineEdit_410.text())*1000
        T_Duty=1/T_Duty
        T_Duty=str("%.7f" % float(T_Duty ) )
        self.N6705C.write('ARB:FUNC:SHAP TRAP, (@4)')         
        self.N6705C.write('ARB:FUNC:TYPE CURR, (@4)')   
        self.N6705C.write('ARB:CURR:TRAP:STAR '+ A_Lo +',(@4)')             #Low
        self.N6705C.write('ARB:CURR:TRAP:TOP '  + A_Hi +',(@4)')               #High
        T_Start=  '0'
        self.N6705C.write('ARB:CURR:TRAP:STAR:TIM '+ T_Start +',(@4)') 
        SlewRate=float(self.lineEdit_407.text())
        T_Rise=  str((( float(A_Hi)- float(A_Lo))*1E-6 )/SlewRate)
        self.N6705C.write('ARB:CURR:TRAP:RTIM '+ T_Rise +',(@4)')   
        T_Top= str(float(T_Duty)*0.5)
        self.N6705C.write('ARB:CURR:TRAP:TOP:TIM '+ T_Top +',(@4)')   
        T_Fall=  str((( float(A_Hi)- float(A_Lo))*1E-6 )/SlewRate)
        self.N6705C.write('ARB:CURR:TRAP:FTIM '+ T_Fall +',(@4)')     
        T_End= str(float(T_Duty)*0.5)
        self.N6705C.write('ARB:CURR:TRAP:END:TIM '+ T_End +',(@4)')     
        self.N6705C.write('ARB:COUN INF, (@4)')    #ARB:SEQ:COUN 10, (@1)   
        self.N6705C.write('CURR:MODE ARB,(@4)')
        self.N6705C.write('OUTP ON, (@4)') 
        self.N6705C.write("INIT:TRAN (@4)")
        self.N6705C.write('*TRG') 
        # Trig          
        T_POSition='50'
        self.SCOPE1.write('HORizontal:MAIn:POSition '+T_POSition)
        self.SCOPE1.write('TRIGGER:A:EDGE:SOURCE CH4')
        self.SCOPE1.write('TRIGGER:A:EDGE:SLOPE FALL')    
        TTL=str((float(A_Hi )*0.5))   
        self.SCOPE1.write('TRIGGER:A:LEVEL:CH4 '+TTL)
        self.SCOPE1.write('TRIGger:A:Mode Auto')       
        self.N6705C.write('OUTP ON, (@'+DC_CH+')')   

   




   
