            #A_Lo= self.lineEdit_409.text() 
            #A_Hi = self.lineEdit_405.text() 
            T_Duty=float(self.lineEdit_410.text())*1000
            T_Duty=1/T_Duty
            T_Duty=str("%.7f" % float(T_Duty ) )
            self.N6705C.write('ARB:FUNC:TYPE CURR, (@4)')             
            self.N6705C.write('ARB:FUNC:SHAP TRAP, (@4)')         
  
            self.N6705C.write('ARB:CURR:TRAP:STAR '+ A_Lo +',(@4)')             #Low
