            T_Start=  '0'
            self.N6705C.write('ARB:CURR:TRAP:STAR:TIM '+ T_Start +',(@4)') 
            SlewRate=float(self.lineEdit_407.text())
            T_Rise=  str((( float(A_Hi)- float(A_Lo))*1E-6 )/SlewRate)
            self.N6705C.write('ARB:CURR:TRAP:RTIM '+ T_Rise +',(@4)')   
            T_Top= str(float(T_Duty)*0.5)
            self.N6705C.write('ARB:CURR:TRAP:TOP:TIM '+ T_Top +',(@4)')   
