def Scope_Initial(self):
    self.SCOPE1.write('CLEAR ALL')
    self.SCOPE1.write('ACQuire:STOPAfter RUNSTop')  # or    
    self.SCOPE1.write("SELECT:CH1 OFF")
    self.SCOPE1.write("SELECT:CH2 OFF")
    self.SCOPE1.write("SELECT:CH3 OFF")
    self.SCOPE1.write("SELECT:CH4 OFF")
    self.SCOPE1.write('MEASU:MEAS1:STATE OFF')
    self.SCOPE1.write('MEASU:MEAS2:STATE OFF')
    self.SCOPE1.write('MEASU:MEAS3:STATE OFF')
    self.SCOPE1.write('MEASU:MEAS4:STATE OFF')
    self.SCOPE1.write('MEASU:MEAS5:STATE OFF')
    self.SCOPE1.write('MEASU:MEAS6:STATE OFF')    
    self.SCOPE1.write('MEASU:MEAS7:STATE OFF')
    self.SCOPE1.write('MEASU:MEAS8:STATE OFF')         
    self.SCOPE1.write('CURSor:FUNCtion OFF')
    self.SCOPE1.write("ACQuire:STATE RUN")
    self.SCOPE1.write('FASTAcq:STATE OFF')   
    self.SCOPE1.write("SELECT:MATH1"+' OFF') 
    self.SCOPE1.write('MEASUrement:ANNOTation:STATE OFF')
    self.SCOPE1.write('HORIZONTAL:ROLL OFF')  
    self.SCOPE1.write("CH3"+":OFFSET"+" "+'0') #  <----------    
 

def Set_Scope(self):
    global SetCH, Label_Name, Level, Position, Offset, BandWidth, \
                Trig_CH, Trig_Pos, Trig_Level, Trig_Slope, \
                TimeScale, SampleRate, RecordLength, \
                Single_ON
                

    self.SCOPE1.write("SELECT:CH1 OFF")
    self.SCOPE1.write("SELECT:CH2 OFF")
    self.SCOPE1.write("SELECT:CH3 OFF")
    self.SCOPE1.write("SELECT:CH4 OFF")            
    self.SCOPE1.write("SELECT:CH"+SetCH+" ON")
    self.SCOPE1.write("CH1"+":SCALE"+" "+ Level )
    self.SCOPE1.write("CH"+SetCH +":OFFSET"+" "+Offset)     
    self.SCOPE1.write("CH"+SetCH +':Position '+ Position)    
    
    if self.radioButton_168.isChecked(): #5000 Series
        self.SCOPE1.write("CH"+SetCH +':LABel:NAMe '+ '"'+Label_Name+'"')   
        if  BandWidth == "20":
            self.SCOPE1.write("CH"+SetCH  +':BANDWIDTH TwEnty')     
    if self.radioButton_167.isChecked():  #4000 Series
        self.SCOPE1.write("CH"+SetCH  +':LABel '+ '"'+Label_Name+'"') 
        if  BandWidth == "20":
            self.SCOPE1.write("CH"+SetCH  +':BANDWIDTH 20E6')        
    if  BandWidth == "Full":
        self.SCOPE1.write("CH"+SetCH  +':BANDWIDTH FULl')     
        
        
    self.SCOPE1.write('HORizontal:MODE CONStant') #{AUTO|CONStant|MANual}   
    #@@@@@@@@@@@@@@@@@@@@@@
 
    #@@@@@@@@@@@@@@@@@@@@@@
    if self.radioButton_168.isChecked():  #5000
        self.SCOPE1.write("HORizontal:MODE:SCAle "+ "0.02")
    if self.radioButton_167.isChecked():  #4000
        self.SCOPE1.write("HORizontal:SCAle "+ "0.02")   
    SampleRate_V=float(SampleRate) *1E6
    self.SCOPE1.write('HORizontal:MODE:SAMPLERate '+str(SampleRate_V) )
    RECORDLENGTH_V=float(RecordLength) *1E6
    self.SCOPE1.write('HORizontal:MODE:RECORDLENGTH '+ str(RECORDLENGTH_V))      
    
    #***************************************************************************
    # Trigger Setting
    # **************************************************************************
    #Trigger Source

    self.SCOPE1.write('TRIGGER:A:EDGE:SOURCE CH'+SetCH  )
    self.SCOPE1.write('TRIGGER:A:LEVEL:CH'+ SetCH+' '+Trig_Level  )
    self.SCOPE1.write('TRIGGER:A:EDGE:SLOPE '+Trig_Slope) 
    self.SCOPE1.write('ACQuire:STOPAfter SEQuence')  # or RUNSTop   
    T_POSition= Trig_Pos 
    if self.radioButton_167.isChecked():  #4000 series scope
        self.SCOPE1.write('HORizontal:POSition '+T_POSition)   
        self.SCOPE1.write("HORizontal:DELay:MODe OFF") 
    else:    
        self.SCOPE1.write('HORizontal:MAIn:POSition '+T_POSition)


 
    if Single_ON==1:    
        self.SCOPE1.write('ACQuire:STOPAfter SEQuence')  # or RUNSTop    
    else:
        self.SCOPE1.write('ACQuire:STOPAfter  RUNSTop')  # or RUNSTop        
    TimeScale_V=float(TimeScale) *1E-6
    if self.radioButton_168.isChecked(): #5000 Series
        self.SCOPE1.write("HORizontal:MODE:SCAle "+ str(TimeScale_V) )
    if self.radioButton_167.isChecked(): #4000 Series
        self.SCOPE1.write("HORizontal:SCAle "+ str(TimeScale_V)  )     
    SampleRate_V=float(SampleRate) *1E6
    self.SCOPE1.write('HORizontal:MODE:SAMPLERate '+str(SampleRate_V) )
    
    
def VoltageLevel_Spec(self):    
    self.tabWidget_2.setCurrentWidget(self.tab_StandardItem) 
    self.tabWidget_6.setCurrentWidget(self.tab_Level)
    self.tabWidget_3.setCurrentWidget(self.tab_Summary)
    
    V_OUT=float(self.lineEdit_586.text()  )        
    # Voltage Level
    Spec= float (self.lineEdit_338.text()  )/100
    Low_limit=str("%.3f" % (float(V_OUT) *(1- Spec)  ) )
    self.lineEdit_358.setText(Low_limit)         
    High_limit=str("%.3f" % (float(V_OUT) *(1+ Spec) ) )
    self.lineEdit_350.setText(High_limit)     
    # Voltage Ripple
    Spec= float (self.lineEdit_342.text()  )/100
    High_limit=str("%.3f" % (float(V_OUT) *( Spec) ) )
    self.lineEdit_351.setText(High_limit)     
    #Overshoot
    Spec= float (self.lineEdit_343.text()  )
    High_limit=str("%.3f" % ( Spec)  )
    self.lineEdit_352.setText(High_limit)         
    #Undershoot
    Spec= float (self.lineEdit_344.text()  )
    High_limit=str("%.3f" % ( Spec)  )
    self.lineEdit_353.setText(High_limit)    
    # Load Transient
    Spec= float (self.lineEdit_345.text()  )/100
    High_limit=str("%.3f" % (float(V_OUT) *( Spec) ) )
    self.lineEdit_355.setText(High_limit)     
    # Load Regulation
    Spec= float (self.lineEdit_347.text()  )
    High_limit=str("%.0f" % ( Spec)  )
    self.lineEdit_356.setText(High_limit)     
    # Line Regulation
    Spec= float (self.lineEdit_348.text()  )/100
    Low_limit=str("%.3f" % (float(V_OUT) *(1- Spec)  ) )
    self.lineEdit_360.setText(Low_limit)         
    High_limit=str("%.3f" % (float(V_OUT) *(1+ Spec) ) )
    self.lineEdit_357.setText(High_limit)     
